showcases.customSetup:
// 1. Physical GI Hemisphere: Sky cyan bounce from above, magenta floor bounce from below
const giHemi = new THREE.HemisphereLight(0x5599bb, 0x662266, 0.40);
scene.add(giHemi);

// 2. Lift ambient indirect bounce via environmentIntensity and calibrated exposure
scene.environmentIntensity = 1.35;
renderer.toneMappingExposure = 0.94;

scene.traverse((obj) => {
  if (obj.isLight) {
    const pName = obj.parent ? obj.parent.name : '';
    if (obj.name === 'Point.005' || pName === 'Point.005' || obj.name === 'Point.007' || pName === 'Point.007') {
      obj.intensity = 60.0;
    }
    if (obj.name === 'Light.001' || pName === 'Light.001') {
      obj.intensity = 160.0;
    }
  }
  // 3. White Billboard Panel: In Cycles, 200W emission blows out to pure white under AgX
  if (obj.isMesh && obj.name === 'Plane.015') {
    const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
    mats.forEach((m) => {
      m.color.set(0xeeeeff);
      m.emissiveIntensity = 8.0;
    });
  }
});

// Eliminate self-shadowing acne on holographic platform
  scene.traverse((o) => {
    if (o.isLight && o.shadow) {
      o.shadow.bias = -0.0003;
      o.shadow.normalBias = 0.035;
    }
    // Boost cyan holographic ring emission core
    if (o.isMesh && o.material && (o.name.includes('Torus') || o.name.includes('Circle'))) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      mats.forEach((m) => {
        if (m.emissive) {
          m.emissiveIntensity = Math.max(m.emissiveIntensity || 1.0, 2.2);
        }
      });
    }
  });

// Turn off tiny Point light
scene.traverse(o => {
  if (o.isLight && o.name === 'Point') o.intensity = 0;
});

// Overhead softbox
const top = new THREE.DirectionalLight(0xfff0ea, 4.0);
top.position.set(2, 20, 0);
scene.add(top);

// Key softbox from left-rear
const key = new THREE.DirectionalLight(0xffeedd, 5.5);
key.position.set(-15, 12, -12);
key.castShadow = true;
key.shadow.bias = -0.0003;
key.shadow.normalBias = 0.035;
scene.add(key);

// Right front rim softbox
const rim = new THREE.DirectionalLight(0xffffff, 3.4);
rim.position.set(12, 10, 10);
scene.add(rim);

// Ambient floor & backdrop fill matching Cycles AgX dark maroon [21, 5, 11]
const fill = new THREE.AmbientLight(0x2d0b13, 0.95);
scene.add(fill);

// Convert car body materials to automotive clearcoat
scene.traverse(o => {
  if (o.isMesh) {
    if (o.name.includes('Background') || o.name.includes('Drape')) {
      o.castShadow = false;
      o.receiveShadow = false;
    }
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      mats.forEach((m, idx) => {
        if (m.name === 'Gloss Red') {
          const phys = new THREE.MeshPhysicalMaterial({
            color: m.color,
            map: m.map,
            roughness: 0.28,
            metalness: 0.12,
            clearcoat: 1.0,
            clearcoatRoughness: 0.05,
            side: m.side
          });
          if (Array.isArray(o.material)) o.material[idx] = phys;
          else o.material = phys;
        }
      });
    }
  }
});

// 1. Soften Area light shafts entering the stormwater drain
  scene.traverse((o) => {
    if (o.isSpotLight) {
      o.angle = Math.min(Math.PI * 0.46, o.angle * 1.35);
      o.penumbra = 0.85;
      if (o.shadow) {
        o.shadow.bias = -0.0003;
        o.shadow.normalBias = 0.035;
      }
    }
    if (o.isPointLight) {
      // Warm maintenance worklights
      o.intensity *= 2.0;
      o.distance = 15.0;
    }
  });

  // 2. Concrete tunnel multi-bounce diffuse GI
  const hemi = new THREE.HemisphereLight(0x88aacc, 0x33261a, 0.45);
  scene.add(hemi);

  const ambient = new THREE.AmbientLight(0x202830, 0.3);
  scene.add(ambient);

// 1. Calibrate background color matching Cycles AgX World
scene.background = new THREE.Color('#39393a');

// 2. Exact Blender camera translation & optical targeting
camera.position.set(31.776279, 10.746194, 41.236115);
camera.fov = 39.6;
controls.target.set(-1.388773, 7.239217, 1.992894);
camera.lookAt(controls.target);
camera.updateProjectionMatrix();

// 3. Shadow parameters on Sun & Spot + Ambient bounce to lift crushed shadows
scene.traverse((obj) => {
  if (obj.isLight) {
    if (obj.isDirectionalLight) {
      obj.intensity = 0.95;
      obj.castShadow = true;
      obj.shadow.bias = -0.0003;
      obj.shadow.normalBias = 0.035;
      obj.shadow.mapSize.set(2048, 2048);
    } else if (obj.isSpotLight) {
      obj.intensity = 1.20;
      obj.angle = Math.PI * 0.44;
      obj.penumbra = 0.85;
      obj.castShadow = true;
      obj.shadow.bias = -0.0003;
      obj.shadow.normalBias = 0.035;
    }
  }
  if (obj.isMesh) {
    obj.castShadow = true;
    obj.receiveShadow = true;
  }
});

// 4. Ambient fill to lift cavity and cast shadows matching Cycles multi-bounce
const ambient = new THREE.AmbientLight(0x282a2c, 0.45);
scene.add(ambient);

renderer.toneMappingExposure = 1.0;

// 1. Disable shadow casting on glass meshes
  scene.traverse((o) => {
    if (o.isMesh && o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      if (mats.some(m => (m.transmission && m.transmission > 0.05) || (m.name && m.name.toLowerCase().includes('glass')))) {
        o.castShadow = false;
      }
    }
    if (o.isSpotLight && o.shadow) {
      o.shadow.bias = -0.0003;
      o.shadow.normalBias = 0.035;
    }
  });

  // 2. Calibrated IBL
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
  scene.environmentIntensity = 0.26;

  // 3. Hemisphere GI fill (Sky: cool blue-cyan from Area.001/002, Ground: warm amber reflection)
  const hemi = new THREE.HemisphereLight(0x70aaff, 0x553311, 0.45);
  scene.add(hemi);
